solution.javascript:
function findOrder(numCourses, prerequisites) {
  const adj = Array.from({length: numCourses}, () => []), indeg = Array(numCourses).fill(0);
  for (const [a,b] of prerequisites) { adj[b].push(a); indeg[a]++; }
  const q = [];
  for (let i=0;i<numCourses;i++) if (indeg[i]===0) q.push(i);
  const result = [];
  while (q.length) {
    const v = q.shift();
    result.push(v);
    for (const u of adj[v]) if (--indeg[u]===0) q.push(u);
  }
  return result.length === numCourses ? result : [];
}

solution.cpp:
vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
    vector<vector<int>> adj(numCourses);
    vector<int> indeg(numCourses);
    for (auto& p : prerequisites) { adj[p[1]].push_back(p[0]); indeg[p[0]]++; }
    queue<int> q;
    for (int i=0;i<numCourses;i++) if (indeg[i]==0) q.push(i);
    vector<int> result;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        result.push_back(v);
        for (int u : adj[v]) if (--indeg[u]==0) q.push(u);
    }
    return result.size() == numCourses ? result : vector<int>();
}
